package io.fireflysoftware.common.config.core.authority;

import io.fireflysoftware.common.config.interfaces.documentissuer.DocumentIssuerContracts.*;
import org.junit.jupiter.api.Test;
import java.nio.charset.StandardCharsets;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class DocumentIssuerCodecTest {
    static final String TENANT="10000000-0000-4000-8000-000000000001";
    static final String ISSUER="10000000-0000-4000-8000-000000000002";
    static final String BRAND="10000000-0000-4000-8000-000000000003";
    static final String ACTION="10000000-0000-4000-8000-000000000004";
    static final String PUBLICATION="10000000-0000-4000-8000-000000000005";
    static SourceSnapshot source() { return new SourceSnapshot(TENANT,4,BRAND,7,9,"tenant-one","Tenant One",true,true,"https://assets.example/logo.svg","#123456","Tenant document footer"); }
    static Definition definition() { return new Definition(ISSUER,1,"DEPOSIT_DOCS","Tenant Documents","documents@example.test",List.of(new Use(Purpose.DEPOSIT_ACCOUNT_ENROLLMENT,"ACCOUNT_AGREEMENT","en-US")),source(),1000,10000); }
    static String prepareJson() { return "{\"actionId\":\""+ACTION+"\",\"publicationId\":\""+PUBLICATION+"\",\"expectedGeneration\":0,\"definition\":"+json(definition())+"}"; }
    static String json(Object value) { try { return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(value); } catch(Exception e) {throw new AssertionError(e);} }
    static byte[] bytes(String value) { return value.getBytes(StandardCharsets.UTF_8); }
    static Definition withSource(SourceSnapshot s) { var d=definition();return new Definition(d.issuerId(),d.revision(),d.issuerCode(),d.displayName(),d.contactEmail(),d.uses(),s,d.effectiveFromEpochMillis(),d.effectiveUntilEpochMillis()); }
    @Test void strictPrepareRetainsOriginalAndExactFacts() { var raw=prepareJson();var decoded=DocumentIssuerCodec.prepare(TENANT,bytes(raw));assertEquals(raw,decoded.originalJson());assertEquals(definition(),decoded.request().definition());assertEquals(64,decoded.intentDigest().length()); }
    @Test void objectOrderDoesNotAlterCanonicalDigest() { var raw=prepareJson();var reordered=raw.replace("{\"actionId\":\""+ACTION+"\",\"publicationId\":\""+PUBLICATION+"\",\"expectedGeneration\":0,", "{\"expectedGeneration\":0,\"publicationId\":\""+PUBLICATION+"\",\"actionId\":\""+ACTION+"\",");assertEquals(DocumentIssuerCodec.prepare(TENANT,bytes(raw)).intentDigest(),DocumentIssuerCodec.prepare(TENANT,bytes(reordered)).intentDigest()); }
    @Test void duplicateUnknownAndTrailingFieldsRefuse() { for(var raw:List.of(prepareJson()+" {}",prepareJson().replace("\"expectedGeneration\":0","\"expectedGeneration\":0,\"expectedGeneration\":0"),prepareJson().replace("\"expectedGeneration\":0","\"expectedGeneration\":0,\"licenseApproved\":true"))) assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.prepare(TENANT,bytes(raw))); }
    @Test void invalidUtf8AndSizeRefuse() { assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.prepare(TENANT,new byte[]{(byte)0xc3,0x28}));assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.prepare(TENANT,new byte[65537])); }
    @Test void crossTenantRefuses() { assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.prepare(BRAND,bytes(prepareJson()))); }
    @Test void zeroAndNoncanonicalUuidRefuse() { for(var id:List.of("00000000-0000-0000-0000-000000000000","1-1-1-1-1")) assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.prepare(TENANT,bytes(prepareJson().replace(ACTION,id)))); }
    @Test void sourceVersionsMustBeRealNonnegativeAndGenerationPositive() {var s=source();for(var v:List.of(-1L,Long.MAX_VALUE))assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.validate(withSource(new SourceSnapshot(TENANT,v,BRAND,7,9,s.tenantCode(),s.tenantName(),true,true,s.logoUrl(),s.primaryColor(),s.footerText()))));assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.validate(withSource(new SourceSnapshot(TENANT,4,BRAND,7,0,s.tenantCode(),s.tenantName(),true,true,s.logoUrl(),s.primaryColor(),s.footerText())))); }
    @Test void inactiveSourcesCannotPreparePositivePublication() { var s=source();for(boolean tenantActive:List.of(false,true))assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.validate(withSource(new SourceSnapshot(TENANT,4,BRAND,7,9,s.tenantCode(),s.tenantName(),tenantActive,false,s.logoUrl(),s.primaryColor(),s.footerText())))); }
    @Test void fixedWindowMustBeOrderedAndFinite() { var d=definition();for(long end:List.of(1000L,Long.MAX_VALUE))assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.validate(new Definition(ISSUER,1,d.issuerCode(),d.displayName(),d.contactEmail(),d.uses(),source(),1000,end))); }
    @Test void duplicateUsesAndMissingUseRefuse() {var d=definition();for(var uses:List.of(List.<Use>of(),List.of(d.uses().getFirst(),d.uses().getFirst())))assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.validate(new Definition(ISSUER,1,d.issuerCode(),d.displayName(),d.contactEmail(),uses,source(),1000,10000))); }
    @Test void localeIsExactAndNoNormalizationIsInvented() { var d=definition();assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.validate(new Definition(ISSUER,1,d.issuerCode(),d.displayName(),d.contactEmail(),List.of(new Use(Purpose.DEPOSIT_ACCOUNT_ENROLLMENT,"ACCOUNT_AGREEMENT","en-us")),source(),1000,10000))); }
    @Test void logoIsMetadataAndMustBeAnHttpsReferenceWithoutCredentials() {var s=source();for(var url:List.of("file:///secret","http://example.test/logo","https://user:pass@example.test/logo"))assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.validate(withSource(new SourceSnapshot(TENANT,4,BRAND,7,9,s.tenantCode(),s.tenantName(),true,true,url,s.primaryColor(),s.footerText())))); }
    @Test void sourceGenerationAndExactPresentationAreDigestBound() {var s=source();var digest=DocumentIssuerCodec.definitionDigest(definition());assertNotEquals(digest,DocumentIssuerCodec.definitionDigest(withSource(new SourceSnapshot(TENANT,4,BRAND,7,10,s.tenantCode(),s.tenantName(),true,true,s.logoUrl(),s.primaryColor(),s.footerText()))));assertNotEquals(digest,DocumentIssuerCodec.definitionDigest(withSource(new SourceSnapshot(TENANT,4,BRAND,7,9,s.tenantCode(),"Changed",true,true,s.logoUrl(),s.primaryColor(),s.footerText())))); }
    @Test void decisionOperationIsBackendClosedAndDigestBound() {var d=new Decision(ACTION,ISSUER,PUBLICATION,1,DocumentIssuerCodec.definitionDigest(definition()),1,"APPROVED");var publish=DocumentIssuerCodec.decision(TENANT,Operation.PUBLISH,bytes(json(d)));var revoke=DocumentIssuerCodec.decision(TENANT,Operation.REVOKE,bytes(json(d)));assertNotEquals(publish.intentDigest(),revoke.intentDigest());assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.decision(TENANT,Operation.CURRENT,bytes(json(d)))); }
    @Test void immutableListAndOpaqueDiagnosticForms() {var d=definition();assertThrows(UnsupportedOperationException.class,()->d.uses().clear());assertFalse(d.toString().contains("Tenant"));assertFalse(source().toString().contains("https://"));assertFalse(DocumentIssuerCodec.prepare(TENANT,bytes(prepareJson())).toString().contains(ACTION)); }
    @Test void numericSyntaxCannotCoerceVersionOrClock() { for(var value:List.of("\"0\"","0.0","1e0","-0"))assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.prepare(TENANT,bytes(prepareJson().replace("\"expectedGeneration\":0","\"expectedGeneration\":"+value)))); }
    @Test void storedDefinitionRoundtripDelegatesSameDigestWithoutRenewal() {var d=definition();var decoded=DocumentIssuerCodec.decodeDefinition(bytes(DocumentIssuerCodec.definitionJson(d)));assertEquals(d,decoded);assertEquals(DocumentIssuerCodec.definitionDigest(d),DocumentIssuerCodec.definitionDigest(decoded));assertEquals(10000,decoded.effectiveUntilEpochMillis());}
    @Test void storedDefinitionCannotHideUnknownOrDuplicateFields() {var raw=json(definition());assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.decodeDefinition(bytes(raw.replace("\"revision\":1","\"revision\":1,\"revision\":1"))));assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.decodeDefinition(bytes(raw.replace("\"revision\":1","\"revision\":1,\"licensed\":true"))));}
    static Receipt receipt(){return new Receipt(TENANT,ISSUER,PUBLICATION,1,2,ACTION,Operation.PUBLISH,State.PUBLISHED,DocumentIssuerCodec.definitionDigest(definition()),"a".repeat(64),2000);}
    @Test void receiptRoundtripKeepsActionAndRetainedOutcomeImmutable(){var r=receipt();var parsed=DocumentIssuerCodec.decodeReceipt(bytes(DocumentIssuerCodec.receiptJson(r)));assertEquals(r,parsed);assertEquals(DocumentIssuerCodec.receiptDigest(r),DocumentIssuerCodec.receiptDigest(parsed));assertNotEquals(DocumentIssuerCodec.definitionDigest(definition()),DocumentIssuerCodec.receiptDigest(parsed));}
    @Test void inconsistentOutcomeAndInvalidScopeCannotBecomeReceipt(){var r=receipt();assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.receiptJson(new Receipt(r.tenantId(),r.issuerId(),r.publicationId(),1,2,ACTION,Operation.PUBLISH,State.REVOKED,r.definitionDigest(),r.intentDigest(),2000)));assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.decodeReceipt(bytes(json(r).replace(TENANT,"00000000-0000-0000-0000-000000000000"))));}
    @Test void receiptDuplicateUnknownAndTrailingFieldsRefuse(){var raw=json(receipt());for(var changed:List.of(raw+"{}",raw.replace("\"generation\":2","\"generation\":2,\"generation\":2"),raw.replace("\"generation\":2","\"generation\":2,\"admitted\":true")))assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.decodeReceipt(bytes(changed)));}
    @Test void currentReferenceDigestBindsExactUseAndImmutableScope(){
        var r=new Reference(TENANT,ISSUER,PUBLICATION,1,DocumentIssuerCodec.definitionDigest(definition()),definition().uses().getFirst());
        assertNotNull(DocumentIssuerCodec.referenceJson(r));var d=DocumentIssuerCodec.referenceDigest(r);assertNotNull(d);
        assertNotEquals(d,DocumentIssuerCodec.referenceDigest(new Reference(TENANT,ISSUER,PUBLICATION,1,r.definitionDigest(),new Use(Purpose.DEPOSIT_ACCOUNT_ENROLLMENT,"OTHER","en-US"))));
        assertNotEquals(d,DocumentIssuerCodec.referenceDigest(new Reference(TENANT,ISSUER,BRAND,1,r.definitionDigest(),r.use())));
    }
    @Test void malformedCurrentScopeCannotCreateAReferenceDigest(){assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.referenceDigest(new Reference(TENANT,ISSUER,PUBLICATION,0,"0".repeat(64),definition().uses().getFirst())));assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.referenceDigest(new Reference(TENANT,ISSUER,PUBLICATION,1,"0".repeat(64),null)));}
    @Test void publicCurrentRequestNeedsNoInferredStableIssuerIdentity(){var p=new PublicationReference(TENANT,PUBLICATION,1,DocumentIssuerCodec.definitionDigest(definition()),definition().uses().getFirst());assertFalse(DocumentIssuerCodec.publicationReferenceJson(p).contains("issuerId"));assertEquals(64,DocumentIssuerCodec.publicationReferenceDigest(p).length());assertNotEquals(DocumentIssuerCodec.publicationReferenceDigest(p),DocumentIssuerCodec.referenceDigest(new Reference(TENANT,ISSUER,PUBLICATION,1,p.definitionDigest(),p.use())));}
    @Test void publicCurrentRequestStillRejectsMissingUseOrRevision(){assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.publicationReferenceDigest(new PublicationReference(TENANT,PUBLICATION,0,"0".repeat(64),definition().uses().getFirst())));assertThrows(IllegalArgumentException.class,()->DocumentIssuerCodec.publicationReferenceJson(new PublicationReference(TENANT,PUBLICATION,1,"0".repeat(64),null)));}
}
